for (const item of $input.all()) {
  const data = item.json;
  let isValid = true;
  let errorMsg = null;

  if (!data.ticket_id || !data.message || !data.product) {
    isValid = false;
    errorMsg = "Missing required fields: ticket_id, message, or product.";
  }

  if (isValid && data.customer_email) {
    let email = data.customer_email.trim().toLowerCase();
    if (email.endsWith('@gmail.com')) {
      email = email.replace(/\+[^@]+(@gmail\.com)$/, '$1');
    }
    data.customer_email = email;
  }

  data.is_valid = isValid;
  data.error_message = errorMsg;
}
return $input.all();

const currentItems = $input.all();
const validOriginals = $('validation_normalization').all().filter(item => item.json.is_valid === true);

for (let i = 0; i < currentItems.length; i++) {
  const item = currentItems[i];
  const originalData = validOriginals[i] ? validOriginals[i].json : {};
  const aiOutput = item.json.output?.[0]?.content?.[0]?.text;

  item.json = {
    ...originalData,
    intent: aiOutput ? aiOutput.intent : "other",
    confidence: aiOutput ? aiOutput.confidence : 0
  };
}

return currentItems;

for (const item of $input.all()) {
  const data = item.json;
  const subs = data.subscriptions || [];
  const matchingSubs = subs.filter(s => s.product === data.product);
  const activeMatchingSubs = matchingSubs.filter(s => s.status === 'active');

  data.matching_subscription_count = matchingSubs.length;
  data.details = { reason: null };

  if (activeMatchingSubs.length === 1) {
      data.action_type = "cancellation";
      data.action_status = "simulated_success";
  } else if (activeMatchingSubs.length === 0) {
      data.action_type = "cancellation";
      data.action_status = "not_executed";
      data.details.reason = "No active matching subscription found.";
  } else {
      data.action_type = "cancellation";
      data.action_status = "requires_review";
      data.details.reason = "Multiple active matching subscriptions found.";
  }
}
return $input.all();

for (const item of $input.all()) {
  const data = item.json;
  const subs = data.subscriptions || [];
  const matchingSubs = subs.filter(s => s.product === data.product);
  const activeMatchingSubs = matchingSubs.filter(s => s.status === 'active');

  data.matching_subscription_count = matchingSubs.length;
  data.details = { reason: null, billing_provider: null };

  if (activeMatchingSubs.length === 1) {
      data.action_type = "cancellation_with_billing_clarification";
      data.action_status = "simulated_success";
      data.details.billing_provider = activeMatchingSubs[0].billing_provider;
  } else if (activeMatchingSubs.length === 0) {
      data.action_type = "cancellation_with_billing_clarification";
      data.action_status = "not_executed";
      data.details.reason = "No active matching subscription found.";
  } else {
      data.action_type = "cancellation_with_billing_clarification";
      data.action_status = "requires_review";
      data.details.reason = "Multiple active matching subscriptions found.";
  }
}
return $input.all();

for (const item of $input.all()) {
  const data = item.json;
  const subs = data.subscriptions || [];
  const matchingSubs = subs.filter(s => s.product === data.product);

  data.matching_subscription_count = matchingSubs.length;
  data.details = { reason: null };

  if (matchingSubs.length > 0) {
      data.action_type = "refund";
      data.action_status = "simulated_success";
  } else {
      data.action_type = "refund";
      data.action_status = "not_executed";
      data.details.reason = "No matching subscription found for refund.";
  }
}
return $input.all();

for (const item of $input.all()) {
  const data = item.json;
  const message = (data.message || "").toLowerCase();

  data.matching_subscription_count = 0; 
  data.action_type = "technical_troubleshooting";
  data.details = { reason: null, response_context: null };

  const kb = [
    { topic: "freezing", response_context: "Ask the customer to update the app, restart the device, and retry." },
    { topic: "login", response_context: "Ask the customer to verify the account email and reset the password." }
  ];

  let matchedContext = null;
  for (const entry of kb) {
      if (message.includes(entry.topic)) {
          matchedContext = entry.response_context;
          break;
      }
  }

  if (matchedContext) {
      data.action_status = "simulated_success";
      data.details.response_context = matchedContext;
  } else {
      data.action_status = "requires_review";
      data.details.reason = "No relevant KB article found.";
  }
}
return $input.all();

for (const item of $input.all()) {
  const data = item.json;
  data.matching_subscription_count = 0;
  data.action_type = "other_inquiry";
  data.action_status = "queued";
  data.details = { reason: "Routed to manual review in general support queue." };
}
return $input.all();

