const currentItems = $input.all();
const mergeItems = $('Merge').all();

for (let i = 0; i < currentItems.length; i++) {
  const item = currentItems[i];
  const mergeData = mergeItems[i] ? mergeItems[i].json : {};
  const aiOutput = item.json.output?.[0]?.content?.[0]?.text;

  item.json = {
    ...mergeData,
    response_subject: aiOutput ? aiOutput.subject : "Support Update",
    response_message: aiOutput ? aiOutput.message : "Your request is under review."
  };
}

return currentItems;

const logs = [];

for (const item of $input.all()) {
  const d = item.json;
  logs.push({
    json: {
      timestamp: new Date().toISOString(),
      ticket_id: d.ticket_id || null,
      detected_intent: d.intent || "none",
      matching_subscription_count: d.matching_subscription_count || 0,
      action_type: d.action_type || "none",
      action_status: d.action_status || "failed",
      execution_status: d.error_message ? "Failed" : "Success",
      error_message: d.error_message || "",
      response_subject: d.response_subject || "",
      response_message: d.response_message || ""
    }
  });
}

return logs;
